    CONSTRAINT ck_world_clock_detailed_phase_name CHECK (((phase_name = ANY (ARRAY['dawn'::text, 'sunrise'::text, 'morning'::text, 'noon'::text, 'afternoon'::text, 'sunset'::text, 'dusk'::text, 'evening'::text, 'night'::text, 'midnight'::text])) OR (resolution_mode <> 'detailed'::text))),
    CONSTRAINT ck_world_clock_generation_range CHECK (((generation_number >= 1) AND (generation_number <= 3))),
    CONSTRAINT ck_world_clock_month_range CHECK (((month >= 1) AND (month <= 12))),
    CONSTRAINT ck_world_clock_phase_ordinal_range CHECK (((phase_ordinal >= 0) AND (phase_ordinal <= 9))),
    CONSTRAINT ck_world_clock_resolution_mode CHECK ((resolution_mode = ANY (ARRAY['detailed'::text, 'day'::text, 'week'::text, 'month'::text, 'year'::text]))),
    CONSTRAINT ck_world_clock_version_nonneg CHECK ((version >= 0))
);


--
-- Name: world_config; Type: TABLE; Schema: worldsim; Owner: -
--

CREATE TABLE worldsim.world_config (
    id uuid NOT NULL,
    world_id uuid NOT NULL,
    config_version integer NOT NULL,
    is_active boolean DEFAULT false NOT NULL,
    effective_from_phase_index bigint NOT NULL,
    detailed_phase_names jsonb NOT NULL,
    max_days integer NOT NULL,
    max_generations smallint DEFAULT 3 NOT NULL,
    plot_armour_level numeric(5,2) NOT NULL,
    director_privileges jsonb NOT NULL,
    image_budget_per_day smallint NOT NULL,
    macro_simulation_policy jsonb NOT NULL,
    content_policy_version text NOT NULL,
    created_event_id uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT ck_world_config_config_version_positive CHECK ((config_version >= 1)),
    CONSTRAINT ck_world_config_max_days_positive CHECK ((max_days >= 1)),
    CONSTRAINT ck_world_config_max_generations_range CHECK (((max_generations >= 1) AND (max_generations <= 3)))
);


--
-- Name: world_event; Type: TABLE; Schema: worldsim; Owner: -
--

CREATE TABLE worldsim.world_event (
    id uuid NOT NULL,
    world_id uuid NOT NULL,
    sequence_number bigint NOT NULL,
    absolute_phase_index bigint NOT NULL,
    phase_run_id uuid,
    scene_id uuid,
    event_type text NOT NULL,
    initiator_entity_id uuid,
    location_id uuid,
    canonical_summary text NOT NULL,
    structured_facts jsonb NOT NULL,
    importance numeric(5,4) NOT NULL,
    visibility_class text NOT NULL,
    source_kind text NOT NULL,
    source_model_profile_id uuid,
    prompt_version_id uuid,
    random_seed bigint,
    idempotency_key text NOT NULL,
    supersedes_event_id uuid,
    consistency_status text NOT NULL,
    committed_at timestamp with time zone DEFAULT now() NOT NULL,
    director_provenance jsonb,
    npc_provenance jsonb,
    CONSTRAINT ck_world_event_absolute_phase_nonneg CHECK ((absolute_phase_index >= 0)),
    CONSTRAINT ck_world_event_importance_range CHECK (((importance >= (0)::numeric) AND (importance <= (1)::numeric))),
    CONSTRAINT ck_world_event_sequence_positive CHECK ((sequence_number >= 1))
);


